### Configure DynamoDB Table with Multi-attribute GSI (Terraform)

Source: https://github.com/hashicorp/terraform-provider-aws/blob/main/website/docs/r/dynamodb_table.html.markdown

Use this configuration to create an AWS DynamoDB table with multiple Global Secondary Indexes (GSI) that utilize multi-attribute keys. This example demonstrates the use of `key_schema` for defining GSI keys, which is preferred over `hash_key`/`range_key` for GSIs.

```terraform
resource "aws_dynamodb_table" "basic-dynamodb-table" {
  name           = "TournamentMatches"
  billing_mode   = "PROVISIONED"
  read_capacity  = 20
  write_capacity = 20
  hash_key       = "matchId"

  attribute {
    name = "matchId"
    type = "S"
  }

  attribute {
    name = "tournamentId"
    type = "S"
  }

  attribute {
    name = "region"
    type = "S"
  }

  attribute {
    name = "round"
    type = "S"
  }

  attribute {
    name = "bracket"
    type = "S"
  }

  attribute {
    name = "playerId"
    type = "N"
  }

  attribute {
    name = "matchDate"
    type = "S"
  }

  ttl {
    attribute_name = "TimeToExist"
    enabled        = true
  }

  # GSI with multiple HASH keys and multiple RANGE keys using key_schema
  global_secondary_index {
    name = "TournamentRegionIndex"
    key_schema {
      attribute_name = "tournamentId"
      key_type       = "HASH"
    }
    key_schema {
      attribute_name = "region"
      key_type       = "HASH"
    }
    key_schema {
      attribute_name = "round"
      key_type       = "RANGE"
    }
    key_schema {
      attribute_name = "bracket"
      key_type       = "RANGE"
    }
    key_schema {
      attribute_name = "matchId"
      key_type       = "RANGE"
    }
    write_capacity  = 10
    read_capacity   = 10
    projection_type = "ALL"
  }

  # GSI with single HASH key and multiple RANGE keys using key_schema
  global_secondary_index {
    name = "PlayerMatchHistoryIndex"
    key_schema {
      attribute_name = "playerId"
      key_type       = "HASH"
    }
    key_schema {
      attribute_name = "matchDate"
      key_type       = "RANGE"
    }
    key_schema {
      attribute_name = "round"
      key_type       = "RANGE"
    }
    write_capacity  = 10
    read_capacity   = 10
    projection_type = "ALL"
  }

  tags = {
    Name        = "dynamodb-table-1"
    Environment = "production"
  }
}
```

### Basic Example containing Global Secondary Indexes using Multi-attribute keys pattern

Source: https://github.com/hashicorp/terraform-provider-aws/blob/main/website/docs/r/dynamodb_table.html.markdown

For Global Secondary Indexes (GSIs) using multi-attribute keys, the `key_schema` block should be used instead of `hash_key` and `range_key`. The `hash_key` and `range_key` arguments are deprecated when defining multi-attribute keys for GSIs.

